'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parseRow, parseRows, parseRecords, validateFeed, stringifyRow, RowScanner } = require('./src/csv.js');
const { readFeed, writeFeed, createFeedReader } = require('./src/feed.js');

const BOM = String.fromCharCode(0xfeff);
const CHUNKY = 'id,note,qty\r\n1,"a, ""b""\nc",x\r\n2, padded ,\r\n';

test('s1 a separator inside a quoted field stays in the field', () => {
  assert.deepStrictEqual(parseRow('sku-1,"widget, large",4'), ['sku-1', 'widget, large', '4']);
  assert.deepStrictEqual(parseRow('"a,b","c,d"'), ['a,b', 'c,d']);
});

test('s2 a doubled quote inside a quoted field becomes one quote', () => {
  assert.deepStrictEqual(parseRow('sku-2,"the ""large"" one",7'), ['sku-2', 'the "large" one', '7']);
  assert.deepStrictEqual(parseRow('"""quoted"""'), ['"quoted"']);
});

test('s3 trailing empty fields are kept', () => {
  assert.deepStrictEqual(parseRow('sku-3,widget,,'), ['sku-3', 'widget', '', '']);
  assert.deepStrictEqual(parseRow('a,,b'), ['a', '', 'b']);
  assert.deepStrictEqual(parseRow('a,b,""'), ['a', 'b', '']);
});

test('s4 records span lines and readFeed follows them', () => {
  assert.deepStrictEqual(
    parseRows('id,note\n1,"line one\nline two"\n2,plain\n'),
    [['id', 'note'], ['1', 'line one\nline two'], ['2', 'plain']]
  );
  assert.deepStrictEqual(parseRows('a,b\r\nc,d\r\n'), [['a', 'b'], ['c', 'd']]);
  assert.deepStrictEqual(
    readFeed('id,note\n1,"line one\nline two"\n'),
    [{ id: '1', note: 'line one\nline two' }]
  );
});

test('s5 padding comes off unquoted fields only, and a byte order mark is dropped', () => {
  assert.deepStrictEqual(parseRow(' sku-4 , widget '), ['sku-4', 'widget']);
  assert.deepStrictEqual(parseRow('a,   ,b'), ['a', '', 'b']);
  assert.deepStrictEqual(parseRow('a,wid get ,b'), ['a', 'wid get', 'b']);
  assert.deepStrictEqual(parseRow('a," padded ",b'), ['a', ' padded ', 'b']);
  assert.deepStrictEqual(parseRow('a, "b, c" ,d'), ['a', 'b, c', 'd']);
  assert.deepStrictEqual(parseRow(BOM + 'id,note'), ['id', 'note']);
  assert.deepStrictEqual(parseRow(BOM + '"id",note'), ['id', 'note']);
  assert.deepStrictEqual(parseRows(BOM + 'id,note\n1,x\n'), [['id', 'note'], ['1', 'x']]);
  assert.deepStrictEqual(readFeed(BOM + 'id,note\n1,x\n'), [{ id: '1', note: 'x' }]);
});

test('s6 records carry the line they start on and widths are checked', () => {
  const text = 'id,note,qty\n1,"line one\nline two",4\n2,short\n3,a,b,c\n';
  assert.deepStrictEqual(parseRecords(text), [
    { line: 1, row: ['id', 'note', 'qty'] },
    { line: 2, row: ['1', 'line one\nline two', '4'] },
    { line: 4, row: ['2', 'short'] },
    { line: 5, row: ['3', 'a', 'b', 'c'] },
  ]);
  assert.deepStrictEqual(parseRecords('a,b\r\nc,d\r\n'), [
    { line: 1, row: ['a', 'b'] },
    { line: 2, row: ['c', 'd'] },
  ]);
  assert.deepStrictEqual(validateFeed(text), [
    { line: 4, code: 'row_width', expected: 3, actual: 2 },
    { line: 5, code: 'row_width', expected: 3, actual: 4 },
  ]);
  assert.deepStrictEqual(validateFeed('id,note\n1,x\n2,y\n'), []);
  assert.deepStrictEqual(validateFeed(''), []);
});

test('s7 an unterminated quoted field is salvaged and reported', () => {
  const text = 'id,note,flag\n1,"first\nsecond","never closed\n';
  assert.deepStrictEqual(parseRecords(text), [
    { line: 1, row: ['id', 'note', 'flag'] },
    { line: 2, row: ['1', 'first\nsecond', 'never closed\n'], unterminated: 3 },
  ]);
  assert.deepStrictEqual(validateFeed(text), [{ line: 3, code: 'unterminated_quote' }]);
  const narrow = 'a,b,c\nx,"y\n';
  assert.deepStrictEqual(parseRows(narrow), [['a', 'b', 'c'], ['x', 'y\n']]);
  assert.deepStrictEqual(validateFeed(narrow), [{ line: 2, code: 'unterminated_quote' }]);
});

test('s8 stringifyRow quotes only what has to be quoted', () => {
  assert.strictEqual(stringifyRow(['sku-1', 'widget, large', '4']), 'sku-1,"widget, large",4');
  assert.strictEqual(stringifyRow(['a', 'the "large" one']), 'a,"the ""large"" one"');
  assert.strictEqual(stringifyRow(['a', ' padded ', '']), 'a," padded ",');
  assert.strictEqual(stringifyRow(['a', 'line one\nline two']), 'a,"line one\nline two"');
  assert.strictEqual(stringifyRow(['plain', 'x', '4']), 'plain,x,4');
  const fields = ['plain', 'has,comma', 'has "quotes"', ' padded ', 'line\nbreak', '', ''];
  assert.deepStrictEqual(parseRows(stringifyRow(fields)), [fields]);
});

test('s9 writeFeed round-trips through readFeed', () => {
  assert.strictEqual(
    writeFeed([{ id: '1', note: 'line one\nline two' }, { id: '2', note: 'plain, really' }]),
    'id,note\n1,"line one\nline two"\n2,"plain, really"\n'
  );
  assert.strictEqual(writeFeed([{ a: '1', b: '2' }], { crlf: true }), 'a,b\r\n1,2\r\n');
  assert.strictEqual(writeFeed([]), '');
  assert.strictEqual(writeFeed([{ id: '1', note: 'x' }, { id: '2' }]), 'id,note\n1,x\n2,\n');
  const records = [{ id: '1', note: 'has "quotes" and, commas' }, { id: '2', note: ' padded ' }];
  assert.deepStrictEqual(readFeed(writeFeed(records)), records);
});

test('s10 RowScanner parses the same rows across any chunk boundary', () => {
  const whole = parseRows(CHUNKY);
  for (let cut = 0; cut <= CHUNKY.length; cut += 1) {
    const scanner = new RowScanner();
    const rows = scanner.push(CHUNKY.slice(0, cut))
      .concat(scanner.push(CHUNKY.slice(cut)))
      .concat(scanner.end());
    assert.deepStrictEqual(rows, whole, 'split at ' + cut);
  }
  const eager = new RowScanner();
  assert.deepStrictEqual(eager.push('id,note\n1,x\n'), [['id', 'note'], ['1', 'x']]);
  assert.deepStrictEqual(eager.push('2,y\n3,'), [['2', 'y']]);
  assert.deepStrictEqual(eager.push('z\n'), [['3', 'z']]);
  assert.deepStrictEqual(eager.end(), []);
  const partial = new RowScanner();
  assert.deepStrictEqual(partial.push('a,b'), []);
  assert.deepStrictEqual(partial.end(), [['a', 'b']]);
});

test('s11 createFeedReader yields the same records as readFeed', () => {
  const whole = readFeed(CHUNKY);
  assert.strictEqual(whole.length, 2);
  for (let cut = 0; cut <= CHUNKY.length; cut += 1) {
    const reader = createFeedReader();
    const records = reader.push(CHUNKY.slice(0, cut))
      .concat(reader.push(CHUNKY.slice(cut)))
      .concat(reader.end());
    assert.deepStrictEqual(records, whole, 'split at ' + cut);
  }
  const eager = createFeedReader();
  assert.deepStrictEqual(eager.push('id,note\n1,x\n'), [{ id: '1', note: 'x' }]);
  assert.deepStrictEqual(eager.push('2,y\n3,'), [{ id: '2', note: 'y' }]);
  assert.deepStrictEqual(eager.push('z\n'), [{ id: '3', note: 'z' }]);
  assert.deepStrictEqual(eager.end(), []);
  const headerOnly = createFeedReader();
  assert.deepStrictEqual(headerOnly.push('id,note\n').concat(headerOnly.end()), []);
});

