'use strict';

// Row parser and row writer for the vendor product feed.
//
// The feed is comma separated. A quoted field may contain separators, line
// breaks, and quote characters written as a doubled quote. Every separator
// produces a field, including the empty ones the exporter pads rows with.
// Padding spaces around an unquoted field are the exporter's, not the vendor's,
// and come off; a quoted field is taken exactly as it was written.

const DELIM = ',';
const QUOTE = '"';
const BOM = '\uFEFF';

const FIELD = 0; // outside quotes
const QUOTED = 1; // inside quotes
const QUOTE_SEEN = 2; // inside quotes, one quote read, not yet resolved

function isPad(ch) {
  return ch === ' ' || ch === '\t';
}

// Incremental scanner. Every deferred decision - is this quote a closing quote
// or the first half of a doubled one, is this carriage return part of a CRLF -
// is held in the state rather than in a lookahead, so a chunk boundary can fall
// at any offset and the result does not change.
class RowScanner {
  constructor() {
    this.state = FIELD;
    this.value = ''; // the field being built
    this.pad = ''; // padding held back until something follows it
    this.row = [];
    this.started = false; // some character has been read for this record
    this.sawQuote = false; // this field had a quoted section
    this.crOpen = false; // last character was a CR outside quotes
    this.crQuoted = false; // last character was a CR inside quotes
    this.line = 1; // physical line the current record starts on
    this.cursor = 1; // physical line the reader is on
    this.quoteLine = 0; // physical line the open quote sits on
    this.unterminated = 0;
    this.atStart = true; // nothing read yet, so a byte order mark may still come
    this.out = [];
  }

  // Rows plus the line each one started on.
  pushRecords(chunk) {
    let text = chunk === null || chunk === undefined ? '' : String(chunk);
    if (this.atStart && text.length > 0) {
      this.atStart = false;
      if (text[0] === BOM) text = text.slice(1);
    }
    this.out = [];
    for (let i = 0; i < text.length; i += 1) this.read(text[i]);
    const done = this.out;
    this.out = [];
    return done;
  }

  endRecords() {
    this.out = [];
    if (this.state === QUOTE_SEEN) {
      this.state = FIELD; // that quote closed the field
      this.quoteLine = 0;
    }
    if (this.state === QUOTED) this.unterminated = this.quoteLine;
    if (this.started) this.endRecord();
    const done = this.out;
    this.out = [];
    return done;
  }

  push(chunk) {
    return this.pushRecords(chunk).map((rec) => rec.row);
  }

  end() {
    return this.endRecords().map((rec) => rec.row);
  }

  begin() {
    if (!this.started) {
      this.started = true;
      this.line = this.cursor;
    }
  }

  endField() {
    this.row.push(this.value);
    this.value = '';
    this.pad = '';
    this.sawQuote = false;
  }

  endRecord() {
    this.endField();
    const rec = { line: this.line, row: this.row };
    if (this.unterminated) rec.unterminated = this.unterminated;
    this.out.push(rec);
    this.row = [];
    this.started = false;
    this.unterminated = 0;
    this.state = FIELD;
  }

  read(ch) {
    if (this.crOpen) {
      this.crOpen = false;
      if (ch === '\n') return; // the LF of a CRLF whose CR already ended the record
    }
    if (this.crQuoted) {
      this.crQuoted = false;
      if (ch === '\n') {
        this.value += '\n';
        return; // one line break, already counted
      }
    }
    if (this.state === QUOTE_SEEN) {
      if (ch === QUOTE) {
        this.value += QUOTE;
        this.state = QUOTED;
        return;
      }
      this.state = FIELD; // the quote closed the quoted section
      this.quoteLine = 0;
    }
    if (this.state === QUOTED) {
      if (ch === QUOTE) {
        this.state = QUOTE_SEEN;
        return;
      }
      if (ch === '\r') {
        this.value += '\r';
        this.cursor += 1;
        this.crQuoted = true;
        return;
      }
      if (ch === '\n') {
        this.value += '\n';
        this.cursor += 1;
        return;
      }
      this.value += ch;
      return;
    }

    if (ch === DELIM) {
      this.begin();
      this.endField();
      return;
    }
    if (ch === '\r') {
      this.begin();
      this.cursor += 1;
      this.endRecord();
      this.crOpen = true;
      return;
    }
    if (ch === '\n') {
      this.begin();
      this.cursor += 1;
      this.endRecord();
      return;
    }
    if (isPad(ch)) {
      this.pad += ch;
      return;
    }
    if (ch === QUOTE && !this.sawQuote && this.value === '') {
      this.begin();
      this.sawQuote = true;
      this.pad = ''; // padding before an opening quote is the exporter's
      this.quoteLine = this.cursor;
      this.state = QUOTED;
      return;
    }
    this.begin();
    if (!this.sawQuote && this.value === '') this.pad = ''; // leading padding
    else {
      this.value += this.pad; // padding inside the value is the value's
      this.pad = '';
    }
    this.value += ch;
  }
}

// Every record in the text, each with the physical line it starts on. A record
// left open by an unterminated quote also carries `unterminated`, set to the
// line the opening quote sat on.
function parseRecords(text) {
  const source = text === null || text === undefined ? '' : String(text);
  if (source === '') return [];
  const scanner = new RowScanner();
  return scanner.pushRecords(source).concat(scanner.endRecords());
}

// Rows of the whole feed text. A line break inside a quoted field belongs to the
// field; one trailing line break does not start another record.
function parseRows(text) {
  return parseRecords(text).map((rec) => rec.row);
}

// One physical line of the feed, split into its fields.
function parseRow(line) {
  const rows = parseRows(line === null || line === undefined ? '' : String(line));
  return rows.length > 0 ? rows[0] : [''];
}

// Structural problems in a feed, in the order the rows appear. The first record
// is the header. A record left open by an unterminated quote is reported as that
// and is not width checked as well.
function validateFeed(text) {
  const records = parseRecords(text);
  if (records.length === 0) return [];
  const width = records[0].row.length;
  const problems = [];
  records.forEach((rec, i) => {
    if (rec.unterminated) {
      problems.push({ line: rec.unterminated, code: 'unterminated_quote' });
      return;
    }
    if (i > 0 && rec.row.length !== width) {
      problems.push({ line: rec.line, code: 'row_width', expected: width, actual: rec.row.length });
    }
  });
  return problems;
}

function needsQuotes(value) {
  if (value === '') return false;
  if (value.indexOf(DELIM) >= 0 || value.indexOf(QUOTE) >= 0) return true;
  if (value.indexOf('\r') >= 0 || value.indexOf('\n') >= 0) return true;
  return isPad(value[0]) || isPad(value[value.length - 1]);
}

function stringifyField(field) {
  const value = field === null || field === undefined ? '' : String(field);
  if (!needsQuotes(value)) return value;
  return QUOTE + value.split(QUOTE).join(QUOTE + QUOTE) + QUOTE;
}

// One CSV line. A field is quoted only when leaving it bare would change what
// the parser reads back.
function stringifyRow(fields) {
  return (fields || []).map(stringifyField).join(DELIM);
}

module.exports = { parseRow, parseRows, parseRecords, validateFeed, stringifyRow, RowScanner };

