'use strict';

const { parseRows, stringifyRow, RowScanner } = require('./csv.js');

// Turns a downloaded feed into records keyed by the names in the header row.
function readFeed(text) {
  const rows = parseRows(text);
  if (rows.length === 0) {
    return [];
  }
  const header = rows[0];
  return rows.slice(1).map((row) => shape(header, row));
}

function shape(header, row) {
  const record = {};
  header.forEach((name, i) => {
    record[name] = row[i] === undefined ? '' : row[i];
  });
  return record;
}

// Turns records back into feed text. The header is the keys of the first
// record, in that record's order, and every record is written in that column
// order whether or not it carries the key.
function writeFeed(records, options) {
  const list = Array.isArray(records) ? records : [];
  if (list.length === 0) {
    return '';
  }
  const eol = options && options.crlf ? '\r\n' : '\n';
  const header = Object.keys(list[0]);
  const lines = [stringifyRow(header)];
  for (const record of list) {
    lines.push(stringifyRow(header.map((name) => {
      const value = record === null || record === undefined ? undefined : record[name];
      return value === undefined || value === null ? '' : String(value);
    })));
  }
  return lines.join(eol) + eol;
}

// Incremental reader for feeds too large to hold in memory. The first row out
// of the scanner is the header and is never emitted as a record, and the header
// itself may arrive split across chunks.
function createFeedReader() {
  const scanner = new RowScanner();
  let header = null;
  const take = (rows) => {
    const out = [];
    for (const row of rows) {
      if (header === null) {
        header = row;
        continue;
      }
      out.push(shape(header, row));
    }
    return out;
  };
  return {
    push: (chunk) => take(scanner.push(chunk)),
    end: () => take(scanner.end()),
  };
}

module.exports = { readFeed, writeFeed, createFeedReader };

