  const records = [{ id: '1', note: 'has "quotes" and, commas' }, { id: '2', note: ' padded ' }];
  assert.deepStrictEqual(readFeed(writeFeed(records)), records);
});

check('RowScanner does not care where a chunk boundary falls', () => {
  const eager = new RowScanner();
  assert.deepStrictEqual(eager.push('id,note\n1,x\n'), [['id', 'note'], ['1', 'x']]);
  assert.deepStrictEqual(eager.push('2,y\n3,'), [['2', 'y']]);
