  const text = 'id,note,qty\r\n1,"a, ""b""\nc",x\r\n2, padded ,\r\n';
  for (let cut = 0; cut <= text.length; cut += 1) {
    const scanner = new RowScanner();
    const rows = scanner.push(text.slice(0, cut))
      .concat(scanner.push(text.slice(cut)))
      .concat(scanner.end());
    assert.deepStrictEqual(rows, parseRows(text), 'split at ' + cut);
  }
});

